  .db-workspace strong { color: #fff; font-weight: 600; overflow: hidden; text-overflow: ellipsis; }
  .db-label { padding: 12px 10px 6px; color: rgba(255,255,255,.44); font: 700 10px/1.2 inherit; letter-spacing: .08em; text-transform: uppercase; }
  .db-nav { display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: var(--radius-md); color: rgba(255,255,255,.72); font: 500 13px/1 inherit; }
  .db-nav svg { width: 16px; height: 16px; }
  .db-nav.active { background: rgba(255,54,33,.18); color: #fff; box-shadow: inset 2px 0 #FF3621; }
  .db-nav:hover { background: rgba(255,255,255,.07); color: #fff; }
  .db-profile { margin-top: auto; padding: 14px 8px 0; border-top: 1px solid rgba(255,255,255,.10); display: flex; align-items: center; gap: 9px; font-size: 12px; color: rgba(255,255,255,.72); }
  .db-avatar { width: 26px; height: 26px; border-radius: 50%; background: #EEEDE9; color: #0B2026; display: grid; place-items: center; font: 700 10px/1 inherit; }
